package com.plantgrowth.forecasting.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.AccessDeniedException;import jakarta.validation.*;import java.time.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(ApiExceptionHandler.class);@ExceptionHandler({IllegalArgumentException.class,ConstraintViolationException.class}) ResponseEntity<?> bad(Exception e){return ResponseEntity.unprocessableEntity().body(Map.of("timestamp",Instant.now(),"status",422,"code","VALIDATION_ERROR","message",e.getMessage()));}@ExceptionHandler(AccessDeniedException.class) ResponseEntity<?> denied(AccessDeniedException e){return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("timestamp",Instant.now(),"status",403,"code","ACCESS_DENIED","message",e.getMessage()));}@ExceptionHandler(Exception.class) ResponseEntity<?> error(Exception e){log.error("Unhandled API request failure",e);return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now(),"status",500,"code","INTERNAL_ERROR","message","The request could not be completed."));}}
